		map: [ 'albedo', 'base_color', 'basecolor', 'base_colour', 'diffuse', 'colour', 'color', 'map' ],
		roughnessMap: [ 'roughness', 'rough', 'roughness_map' ],
		normalMap: [ 'normal', 'normal_map', 'nrm', 'tangent_normal' ],
		metalnessMap: [ 'metallic', 'metalness', 'metal' ],
