	const dirG1 = pick( raw, 'textures.ktx2_dir' ) || '';
	const joinDir = ( dir, p ) => resolveUrl( baseUrl, ( dir && ! p.startsWith( '/' ) ) ? `${String( dir ).replace( /\/$/, '' )}/${p}` : p );
	const unresolvedKeys = [];
