		mode: materialsMode,
		detail,
		sets: materialSets,
		count: Object.keys( materialSets ).length,
		maps: mapCount,
		constantMaps,
		inGlbMaps,
		withoutUv1: noUv1,
		declaredBytes: setBytes,
		budget: pick( raw, 'budget' ) || null,
